  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brise-Sortil&#232;ge-(Inquisiteur).html&quot; title=&quot;Brise-sortil&#232;ge&quot;&gt;Brise-sortil&#232;ge&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Foi-(Inquisiteur).html&quot; title=&quot;Chasseur de foi&quot;&gt;Chasseur de foi&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Reliques-(Inquisiteur).html&quot; title=&quot;Chasseur de reliques&quot;&gt;Chasseur de reliques&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Sorci&#232;res-(Inquisiteur).html&quot; title=&quot;Chasseur de sorci&#232;res&quot;&gt;Chasseur de sorci&#232;res&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Vampires-(Inquisiteur).html&quot; title=&quot;Chasseur de vampires&quot;&gt;Chasseur de vampires&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Vigilant-(Inquisiteur).html&quot; title=&quot;D&#233;fenseur vigilant&quot;&gt;D&#233;fenseur vigilant&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Exarque-(Inquisiteur).html&quot; title=&quot;Exarque&quot;&gt;Exarque&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Exorciste-(Inquisiteur).html&quot; title=&quot;Exorciste&quot;&gt;Exorciste&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Exterminateur-Sacr&#233;-(Inquisiteur).html&quot; title=&quot;Exterminateur sacr&#233;&quot;&gt;Exterminateur sacr&#233;&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Extracteur-(Inquisiteur).html&quot; title=&quot;Extracteur&quot;&gt;Extracteur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-Tactique-(Inquisiteur).html&quot; title=&quot;Guide tactique&quot;&gt;Guide tactique&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H&#233;r&#233;tique-(Inquisiteur).html&quot; title=&quot;H&#233;r&#233;tique&quot;&gt;H&#233;r&#233;tique&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Iconoclaste-(Inquisiteur).html&quot; title=&quot;Iconoclaste&quot;&gt;Iconoclaste&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Immolateur-(Inquisiteur).html&quot; title=&quot;Immolateur&quot;&gt;Immolateur&lt;/a&gt; (Ifrit) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Infiltrateur-(Inquisiteur).html&quot; title=&quot;Infiltrateur&quot;&gt;Infiltrateur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Loup-Masqu&#233;-(Inquisiteur).html&quot; title=&quot;Loup masqu&#233;&quot;&gt;Loup masqu&#233;&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mangeur-De-P&#234;ch&#233;s-(Inquisiteur).html&quot; title=&quot;Mangeur de p&#234;ch&#233;s&quot;&gt;Mangeur de p&#234;ch&#233;s&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Chasseur-Sacr&#233;-(Inquisiteur).html&quot; title=&quot;Ma&#238;tre chasseur sacr&#233;&quot;&gt;Ma&#238;tre chasseur sacr&#233;&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Parricide-(Inquisiteur).html&quot; title=&quot;Parricide&quot;&gt;Parricide&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Dhampir-(Race).html&quot; title=&quot;Les dhampirs&quot;&gt;Dhampir&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;cheur-(Inquisiteur).html&quot; title=&quot;Pr&#234;cheur&quot;&gt;Pr&#234;cheur&lt;/a&gt; (AM)&lt;/li&gt;
